<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),rule=ref('tukey'),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.bxusage-card')})
watch([dataset,state,rule],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Group A','Group B','Group C']
const samples=computed(()=>dataset.value==='A'?[[10,20,25,30,35,40,90],[20,30,40,50,60],[5,10,15,20,25,30,35]]:dataset.value==='B'?[[0,10,20,30,40],[40,45,50,55,60,65,100],[10,20,30,40,50,60,70]]:[[25,25,25],[0],[50,50,50,50]])
function quantile(a:number[],p:number){const at=(a.length-1)*p,lo=Math.floor(at),hi=Math.ceil(at);return a[lo]+(a[hi]-a[lo])*(at-lo)}
const stats=computed(()=>samples.value.map(values=>{const a=[...values].sort((a,b)=>a-b),q1=quantile(a,.25),median=quantile(a,.5),q3=quantile(a,.75),iqr=q3-q1,inside=rule.value==='minmax'?a:a.filter(v=>v>=q1-1.5*iqr&&v<=q3+1.5*iqr);return{n:a.length,min:a[0],q1,median,q3,max:a[a.length-1],low:inside[0],high:inside[inside.length-1],outliers:rule.value==='minmax'?[]:a.filter(v=>v<q1-1.5*iqr||v>q3+1.5*iqr)}}))
const px=(v:number)=>70+v*2.1
function reset(){dataset.value='A';state.value='ready';selected.value=0;rule.value='tukey'}
</script>
<template>
<section ref="root" class="bxusage-demo" aria-label="Local box plot example"><p>Synthetic values on a fixed 0–100 unit scale. Box = Q1–Q3; line = median. Choose observed min/max whiskers or 1.5×IQR whiskers with outside observations drawn separately. This is not a confidence interval.</p><div class="bxusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="ties">Ties and singleton</option></select></label><label>Whiskers<select v-model="rule"><option value="tukey">1.5 × IQR</option><option value="minmax">Min/max</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="bxusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 330 245" role="img" aria-label="Horizontal box plots on fixed zero to one hundred scale. Linear interpolated quartiles. Exact summaries and raw samples below."><template v-for="v in [0,25,50,75,100]" :key="v"><line class="bxusage-grid" :x1="px(v)" :x2="px(v)" y1="25" y2="190"/><text :x="px(v)" y="211" text-anchor="middle">{{ v }}</text></template><g v-for="(s,i) in stats" :key="i" class="bxusage-row" :class="{selected:selected===i}" :data-index="i"><text x="4" :y="54+i*55">{{ labels[i] }}</text><line class="bxusage-whisker" :x1="px(s.low)" :x2="px(s.high)" :y1="50+i*55" :y2="50+i*55" data-cm="fade"/><path class="bxusage-cap" :d="`M${px(s.low)},${42+i*55} v16 M${px(s.high)},${42+i*55} v16`" data-cm="fade"/><rect class="bxusage-box" :x="px(s.q1)" :y="39+i*55" :width="(s.q3-s.q1)*2.1" height="22" data-cm="fade"/><line class="bxusage-median" :x1="px(s.median)" :x2="px(s.median)" :y1="39+i*55" :y2="61+i*55" data-cm="fade"/><circle v-for="(v,j) in s.outliers" :key="j" class="bxusage-outlier" :cx="px(v)" :cy="50+i*55" r="3" data-cm="fade"/></g><text x="175" y="236" text-anchor="middle">Measured units · same scale for every group</text></svg><div role="group" aria-label="Select group" class="bxusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: N {{ stats[selected].n }}, Q1 {{ stats[selected].q1 }}, median {{ stats[selected].median }}, Q3 {{ stats[selected].q3 }}; whiskers {{ stats[selected].low }}–{{ stats[selected].high }}; outside observations {{ stats[selected].outliers.join(', ')||'none' }}.</p><table class="bxusage-data"><caption>Quartiles and actual whiskers, dataset {{ dataset }}</caption><thead><tr><th scope="col">Group</th><th scope="col">Q1</th><th scope="col">Med</th><th scope="col">Q3</th><th scope="col">Ends</th></tr></thead><tbody><tr v-for="(s,i) in stats" :key="i"><th scope="row">{{ labels[i] }}</th><td>{{ s.q1 }}</td><td>{{ s.median }}</td><td>{{ s.q3 }}</td><td>{{ s.low }}–{{ s.high }}</td></tr></tbody></table><details><summary>Raw samples and sample sizes</summary><p v-for="(values,i) in samples" :key="i" class="bxusage-samples">{{ labels[i] }} (N={{ values.length }}): {{ values.join(', ') }}</p></details><p class="bxusage-key">Quartiles use linear interpolation at (N−1)×p in sorted data. IQR fences are Q1−1.5IQR / Q3+1.5IQR; whiskers end at actual observations inside them, not the fence coordinates. A singleton or all ties has a zero-width box/whisker but a visible median line.</p></template><p v-else role="status" class="bxusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Samples and summaries are withheld.':'No group records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>



.bxusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.bxusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.bxusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.bxusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.bxusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.bxusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.bxusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.bxusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.bxusage-demo .bxusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.bxusage-choices{display:flex;gap:6px;flex-wrap:wrap}.bxusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.bxusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.bxusage-data{display:table!important;width:100%;font-size:12px}.bxusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.bxusage-data :is(td,th){padding:6px!important}.bxusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}

.bxusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 3}.bxusage-row{opacity:.6}.bxusage-row.selected{opacity:1}.bxusage-whisker,.bxusage-cap{stroke:var(--vp-c-text-1);stroke-width:2}.bxusage-box{fill:var(--vp-c-brand-1);stroke:var(--vp-c-text-1);stroke-width:1}.bxusage-median{stroke:var(--vp-c-text-1);stroke-width:3}.bxusage-outlier{fill:none;stroke:var(--vp-c-text-1);stroke-width:2}.bxusage-key{font-size:12px;color:var(--vp-c-text-2)}
</style>
